package testdata

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// IBKR OAuth reference fixtures (feature 249). vectors.json is generated by ibkr/gen_vectors.py from
// the ibind reference client; never hand-edit it, and regenerate it whenever a PEM changes.
var (
	//go:embed ibkr/signature_key.pem
	IBKRSignatureKeyPEM string
	//go:embed ibkr/encryption_key.pem
	IBKREncryptionKeyPEM string
	//go:embed ibkr/dhparam.pem
	IBKRDHParamPEM string
	//go:embed ibkr/vectors.json
	ibkrVectorsJSON []byte
)

type IBKRVectors struct {
	Meta struct {
		IbindSHA  string `json:"ibind_sha"`
		Generator string `json:"generator"`
	} `json:"meta"`
	Inputs struct {
		BaseURL           string   `json:"base_url"`
		Realm             string   `json:"realm"`
		ConsumerKey       string   `json:"consumer_key"`
		AccessToken       string   `json:"access_token"`
		AccessTokenSecret string   `json:"access_token_secret"`
		Nonces            []string `json:"nonces"`
		Timestamp         string   `json:"timestamp"`
		DHPrimeHex        string   `json:"dh_prime_hex"`
		DHGenerator       int      `json:"dh_generator"`
		DHRandomHex       string   `json:"dh_random_hex"`
	} `json:"inputs"`
	LSTRequest struct {
		Method                 string `json:"method"`
		URL                    string `json:"url"`
		Nonce                  string `json:"nonce"`
		Prepend                string `json:"prepend"`
		DiffieHellmanChallenge string `json:"diffie_hellman_challenge"`
		BaseString             string `json:"base_string"`
		OAuthSignature         string `json:"oauth_signature"`
		Authorization          string `json:"authorization"`
	} `json:"lst_request"`
	LSTReply struct {
		DiffieHellmanResponse        string `json:"diffie_hellman_response"`
		LiveSessionTokenExpiration   int64  `json:"live_session_token_expiration"`
		LiveSessionTokenSignature    string `json:"live_session_token_signature"`
		BadLiveSessionTokenSignature string `json:"bad_live_session_token_signature"`
		LiveSessionToken             string `json:"live_session_token"`
	} `json:"lst_reply"`
	Requests []IBKRRequestVector `json:"requests"`
	Decrypt  struct {
		CiphertextB64         string `json:"ciphertext_b64"`
		PlaintextHex          string `json:"plaintext_hex"`
		WrongKeyCiphertextB64 string `json:"wrong_key_ciphertext_b64"`
	} `json:"decrypt"`
	DHCases []IBKRDHCase `json:"dh_cases"`
}

// IBKRRequestVector is one LST-signed regular request; Params are the query params ibind signed over.
type IBKRRequestVector struct {
	Name               string            `json:"name"`
	Method             string            `json:"method"`
	URL                string            `json:"url"`
	Params             map[string]string `json:"params"`
	Nonce              string            `json:"nonce"`
	BaseString         string            `json:"base_string"`
	OAuthSignature     string            `json:"oauth_signature"`
	Authorization      string            `json:"authorization"`
	LegacySignatureB64 string            `json:"legacy_signature_b64"`
}

type IBKRDHCase struct {
	Name                  string `json:"name"`
	DHServerBHex          string `json:"dh_server_b_hex"`
	DiffieHellmanResponse string `json:"diffie_hellman_response"`
	KBitlen               int    `json:"k_bitlen"`
	LiveSessionToken      string `json:"live_session_token"`
}

var (
	ibkrVectorsOnce sync.Once
	ibkrVectors     IBKRVectors
)

// MustIBKRVectors decodes vectors.json once; callers must not mutate the returned value.
func MustIBKRVectors() *IBKRVectors {
	ibkrVectorsOnce.Do(func() {
		if err := json.Unmarshal(ibkrVectorsJSON, &ibkrVectors); err != nil {
			panic("testdata: decode ibkr/vectors.json: " + err.Error())
		}
	})
	return &ibkrVectors
}
